const b = $input.first().json.body || {};
const s = (v, max=200) => (typeof v === 'string' ? v.trim().slice(0, max) : '');
const fail = (m) => [{ json: { fehler: m, status: 400 } }];

if (s(b.website)) return fail('Anmeldung abgelehnt.');           // Honeypot
const kind = b.kategorie === 'kind';
if (!['erwachsen','kind'].includes(b.kategorie)) return fail('Ungültige Kategorie.');
if (!/^[a-z0-9]{15}$/.test(s(b.event_id, 20))) return fail('Ungültige Challenge.');
const name = s(b.name, 100);
if (name.length < 2) return fail('Bitte trag einen Namen ein.');
const email = s(b.email, 200).toLowerCase();
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return fail('Bitte trag eine gültige E-Mail-Adresse ein.');
const jahr = parseInt(b.geburtsjahr, 10), now = new Date().getFullYear();
if (!jahr || jahr < 1920 || jahr > now) return fail('Ungültiges Geburtsjahr.');
if (!['DE','AT','CH'].includes(b.land)) return fail('Wir versenden nur nach Deutschland, Österreich und in die Schweiz.');
const adresse = s(b.adresse, 300);
if (adresse.length < 8) return fail('Bitte trag deine vollständige Adresse ein.');
if (b.agb_akzeptiert !== true) return fail('Bitte akzeptiere die Teilnahmebedingungen.');

const d = { event_id: b.event_id, kategorie: b.kategorie, name, email, geburtsjahr: jahr, land: b.land, adresse };
if (kind) {
  const eltern = s(b.eltern_name, 100);
  if (eltern.length < 2) return fail('Bitte trag den Namen des Elternteils ein.');
  d.eltern_name = eltern; d.eltern_email = email;
} else {
  if (now - jahr < 13) return fail('Für Kinder wähle „Mein Kind“.');
  if (!['maennlich','weiblich','divers'].includes(b.geschlecht)) return fail('Bitte wähle eine Wertung.');
  d.geschlecht = b.geschlecht;
  d.anzeigename = s(b.anzeigename, 40) || name.split(/\s+/)[0];
  if (b.geschlecht === 'divers') {
    if (!['maennlich','weiblich'].includes(b.podium_wahl)) return fail('Bitte wähle die Bestzeit-Wertung.');
    d.podium_wahl = b.podium_wahl;
    d.divers_oeffentlich_optin = b.divers_oeffentlich_optin === true;
  } else {
    d.divers_oeffentlich_optin = false;
  }
}
return [{ json: { ok: true, data: d } }];

const ev = $input.first().json;           // Antwort der Event-Abfrage
const d = $('Validate').first().json.data;
const fail = (m, status=400) => [{ json: { fehler: m, status } }];

if (ev.status !== 'anmeldung_offen') return fail('Die Anmeldung ist nicht geöffnet.');
if (!ev.preis_cent || ev.preis_cent < 50) return fail('Die Anmeldung ist noch nicht geöffnet.');
if (ev.anmeldeschluss) {
  // Anmeldeschluss gilt bis Ende des Tages in Berlin (gespeichert ist Berlin-Mitternacht als UTC)
  const s = new Date(ev.anmeldeschluss.replace(' ', 'T'));
  const ymd = (x) => x.toLocaleDateString('en-CA', { timeZone: 'Europe/Berlin' });
  const [y, m, dd] = ymd(s).split('-').map(Number);
  const n = new Date(Date.UTC(y, m - 1, dd + 1));
  let ende = new Date(n.getTime() - 3600000);
  for (const off of [1, 2]) {
    const t = new Date(n.getTime() - off * 3600000);
    if (ymd(t) === n.toISOString().slice(0, 10) && parseInt(new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Berlin', hour: '2-digit', hourCycle: 'h23' }).format(t), 10) === 0) { ende = t; break; }
  }
  if (Date.now() >= ende.getTime()) return fail('Der Anmeldeschluss ist vorbei.');
}
if (d.kategorie === 'kind') {
  const alter = new Date().getFullYear() - d.geburtsjahr;
  if (ev.kinderdistanz_max_alter && alter > ev.kinderdistanz_max_alter) return fail('Die Kinderdistanz gilt nur bis ' + ev.kinderdistanz_max_alter + ' Jahre.');
}

const items = [{ typ: 'startgebuehr', bezeichnung: ev.name + ' – Startgebühr', betrag_cent: ev.preis_cent }];
if (d.land === 'CH' && ev.aufschlag_ch_cent > 0) {
  items.push({ typ: 'versand_ch', bezeichnung: 'Versandaufschlag Schweiz', betrag_cent: ev.aufschlag_ch_cent });
}
const summe = items.reduce((a, i) => a + i.betrag_cent, 0);

const teilnehmer = {
  event: ev.id, kategorie: d.kategorie, name: d.name, email: d.email,
  geburtsjahr: d.geburtsjahr, status: 'offen',
  agb_akzeptiert_am: new Date().toISOString().replace('T', ' ')
};
['anzeigename','geschlecht','podium_wahl','eltern_name','eltern_email'].forEach(k => { if (d[k]) teilnehmer[k] = d[k]; });
if (d.divers_oeffentlich_optin !== undefined) teilnehmer.divers_oeffentlich_optin = d.divers_oeffentlich_optin;

return [{ json: {
  ok: true, teilnehmer, items, summe, waehrung: (ev.waehrung || 'EUR').toLowerCase(),
  fulfillment: { medaillen_typ: d.kategorie === 'kind' ? 'kind' : 'teilnahme', adresse: d.adresse, land: d.land, versand_status: 'offen' },
  eventName: ev.name
} }];

const c = $('Check Event').first().json;
const t = $('Create Teilnehmer').first().json;
const bst = $('Create Bestellung').first().json;
const parts = [];
const p = { set: (k, v) => parts.push(encodeURIComponent(k) + '=' + encodeURIComponent(String(v))) };
p.set('mode', 'payment');
p.set('locale', 'de');
p.set('customer_email', c.teilnehmer.email);
p.set('success_url', 'https://runrebels.com/danke.html');
p.set('cancel_url', 'https://runrebels.com/#anmeldung');
p.set('metadata[bestellung_id]', bst.id);
p.set('metadata[teilnehmer_id]', t.id);
p.set('payment_intent_data[metadata][bestellung_id]', bst.id);
p.set('payment_intent_data[metadata][teilnehmer_id]', t.id);
c.items.forEach((it, i) => {
  p.set(`line_items[${i}][quantity]`, '1');
  p.set(`line_items[${i}][price_data][currency]`, c.waehrung);
  p.set(`line_items[${i}][price_data][unit_amount]`, String(it.betrag_cent));
  p.set(`line_items[${i}][price_data][product_data][name]`, it.bezeichnung);
});
return [{ json: { body: parts.join('&') } }];
